"""Frozen fixed Run, scoped test facts and unified physical occupancy schema."""
# ruff: noqa: E501

TABLES = ('verification_run_identities', 'test_resource_facts', 'verification_run_versions', 'test_resource_current', 'test_resource_reservations', 'verification_current_runs', 'verification_launch_facts', 'sample_usage_sentinels', 'sample_run_usages')

SCHEMA_SQL = ("\nCREATE TABLE verification_run_identities (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\trequest_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id), \n\tUNIQUE (tenant_id, product_id, request_id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product'))\n)\n\n", 'CREATE INDEX ix_verification_run_identities_tenant_id ON verification_run_identities (tenant_id)', "\nCREATE TABLE test_resource_facts (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\trequest_id UUID NOT NULL, \n\taccepted_request_id UUID NOT NULL, \n\taccepted_request_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\tissuer_key VARCHAR(100) NOT NULL, \n\tissuer_version VARCHAR(100) NOT NULL, \n\tissuer_epoch INTEGER NOT NULL, \n\tnature VARCHAR(16) NOT NULL, \n\texternal_id VARCHAR(160) NOT NULL, \n\tseries_id UUID NOT NULL, \n\trevision INTEGER NOT NULL, \n\tprevious_id UUID, \n\tprevious_revision INTEGER, \n\tstate VARCHAR(16) NOT NULL, \n\tvalid_from TIMESTAMP WITH TIME ZONE NOT NULL, \n\tvalid_until TIMESTAMP WITH TIME ZONE NOT NULL, \n\tbinding JSONB NOT NULL, \n\tdata JSONB NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tsource_basis JSONB NOT NULL, \n\tfact_sha256 VARCHAR(64) NOT NULL, \n\treason TEXT NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id, revision), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, run_id, request_id, id, revision), \n\tUNIQUE (tenant_id, product_id, run_id, series_id, revision), \n\tFOREIGN KEY(tenant_id, product_id, project_id, request_id, accepted_request_id, accepted_request_revision) REFERENCES verification_formal_requests (tenant_id, product_id, project_id, request_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, run_id, request_id, previous_id, previous_revision) REFERENCES test_resource_facts (tenant_id, product_id, project_id, build_id, run_id, request_id, id, revision), \n\tCHECK (revision>0 AND accepted_request_revision>0 AND issuer_epoch>0 AND valid_until>valid_from), \n\tCHECK (state IN ('active','withdrawn') AND nature IN ('real','synthetic') AND visibility IN ('private','product')), \n\tCHECK ((revision=1 AND previous_id IS NULL AND previous_revision IS NULL AND series_id=id) OR (previous_id IS NOT NULL AND previous_id<>id AND previous_revision>0 AND revision=previous_revision+1))\n)\n\n", 'CREATE INDEX ix_test_resource_facts_tenant_id ON test_resource_facts (tenant_id)', "\nCREATE TABLE verification_run_versions (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_version_id UUID NOT NULL, \n\trequest_revision INTEGER NOT NULL, \n\trun_id UUID NOT NULL, \n\trevision INTEGER NOT NULL, \n\tprevious_run_version_id UUID, \n\tprevious_revision INTEGER, \n\towner_id UUID NOT NULL, \n\twriter_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\toperation VARCHAR(80) NOT NULL, \n\trun_snapshot JSONB NOT NULL, \n\texecution_plan JSONB NOT NULL, \n\tplan_sha256 VARCHAR(64) NOT NULL, \n\tinput_snapshot JSONB NOT NULL, \n\tsnapshot_sha256 VARCHAR(64) NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tsource_basis JSONB NOT NULL, \n\tauthority_snapshot JSONB NOT NULL, \n\tintent_digest VARCHAR(64) NOT NULL, \n\treason TEXT NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, request_id, run_id, revision), \n\tUNIQUE (tenant_id, product_id, request_id, run_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, run_id) REFERENCES verification_run_identities (tenant_id, product_id, project_id, build_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, request_id, request_version_id, request_revision) REFERENCES verification_formal_requests (tenant_id, product_id, project_id, request_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id, request_id, run_id, previous_run_version_id, previous_revision) REFERENCES verification_run_versions (tenant_id, product_id, request_id, run_id, id, revision), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tFOREIGN KEY(tenant_id, writer_id) REFERENCES principals (tenant_id, id), \n\tCHECK (build_revision > 0 AND request_revision > 0 AND revision > 0), \n\tCHECK (visibility IN ('private','product') AND status IN ('planned','running')), \n\tCHECK (operation IN ('test.run.plan','test.run.start')), \n\tCHECK ((revision = 1 AND status = 'planned' AND previous_run_version_id IS NULL AND previous_revision IS NULL) OR (revision = 2 AND status = 'running' AND previous_run_version_id IS NOT NULL AND previous_revision = 1))\n)\n\n", 'CREATE INDEX ix_verification_run_versions_tenant_id ON verification_run_versions (tenant_id)', '\nCREATE TABLE test_resource_current (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\trequest_id UUID NOT NULL, \n\tfact_id UUID NOT NULL, \n\tfact_revision INTEGER NOT NULL, \n\tepoch INTEGER NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, run_id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, run_id, request_id, fact_id, fact_revision) REFERENCES test_resource_facts (tenant_id, product_id, project_id, build_id, run_id, request_id, id, revision), \n\tCHECK (fact_revision>0 AND epoch>0)\n)\n\n', 'CREATE INDEX ix_test_resource_current_tenant_id ON test_resource_current (tenant_id)', "\nCREATE TABLE test_resource_reservations (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tfact_id UUID NOT NULL, \n\tfact_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tstate VARCHAR(16) NOT NULL, \n\tintent_digest VARCHAR(64) NOT NULL, \n\tbinding JSONB NOT NULL, \n\treservation JSONB NOT NULL, \n\treservation_sha256 VARCHAR(64) NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tfacts_revision VARCHAR(64) NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, run_id), \n\tUNIQUE (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, run_id) REFERENCES verification_run_identities (tenant_id, product_id, project_id, build_id, id) DEFERRABLE INITIALLY DEFERRED, \n\tFOREIGN KEY(tenant_id, product_id, fact_id, fact_revision) REFERENCES test_resource_facts (tenant_id, product_id, id, revision), \n\tCHECK (revision=1 AND fact_revision>0 AND state='formal' AND visibility IN ('private','product'))\n)\n\n", 'CREATE INDEX ix_test_resource_reservations_tenant_id ON test_resource_reservations (tenant_id)', '\nCREATE TABLE verification_current_runs (\n\tproduct_id UUID NOT NULL, \n\trequest_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\trun_version_id UUID NOT NULL, \n\trun_revision INTEGER NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, request_id), \n\tUNIQUE (tenant_id, product_id, run_id), \n\tFOREIGN KEY(tenant_id, product_id, request_id, run_id, run_version_id, run_revision) REFERENCES verification_run_versions (tenant_id, product_id, request_id, run_id, id, revision), \n\tCHECK (run_revision > 0)\n)\n\n', 'CREATE INDEX ix_verification_current_runs_tenant_id ON verification_current_runs (tenant_id)', "\nCREATE TABLE verification_launch_facts (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_version_id UUID NOT NULL, \n\trequest_revision INTEGER NOT NULL, \n\tnext_request_version_id UUID NOT NULL, \n\tnext_request_revision INTEGER NOT NULL, \n\trun_id UUID NOT NULL, \n\trun_version_id UUID NOT NULL, \n\trun_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\toperation VARCHAR(80) NOT NULL, \n\tinput_snapshot JSONB NOT NULL, \n\tkernel_event JSONB NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tsource_basis JSONB NOT NULL, \n\tauthority_snapshot JSONB NOT NULL, \n\tintent_digest VARCHAR(64) NOT NULL, \n\tsnapshot_sha256 VARCHAR(64) NOT NULL, \n\treason TEXT NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, operation, run_id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, run_id) REFERENCES verification_run_identities (tenant_id, product_id, project_id, build_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, request_id, request_version_id, request_revision) REFERENCES verification_formal_requests (tenant_id, product_id, project_id, request_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id, request_id, run_id, run_version_id, run_revision) REFERENCES verification_run_versions (tenant_id, product_id, request_id, run_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id, project_id, request_id, next_request_version_id, next_request_revision) REFERENCES verification_formal_requests (tenant_id, product_id, project_id, request_id, id, revision), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (revision = 1 AND request_revision > 0 AND run_revision > 0), \n\tCHECK (visibility IN ('private','product')), \n\tCHECK (operation IN ('test.run.plan','verification.schedule.promise','test.run.start'))\n)\n\n", 'CREATE INDEX ix_verification_launch_facts_tenant_id ON verification_launch_facts (tenant_id)', '\nCREATE TABLE sample_usage_sentinels (\n\tproduct_id UUID NOT NULL, \n\tsample_id UUID NOT NULL, \n\tepoch INTEGER NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, sample_id), \n\tFOREIGN KEY(tenant_id, product_id, sample_id) REFERENCES sample_units (tenant_id, product_id, id), \n\tCHECK (epoch>0)\n)\n\n', 'CREATE INDEX ix_sample_usage_sentinels_tenant_id ON sample_usage_sentinels (tenant_id)', "\nCREATE TABLE sample_run_usages (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tsample_id UUID NOT NULL, \n\tsample_revision INTEGER NOT NULL, \n\tactual_configuration_id UUID NOT NULL, \n\tactual_configuration_revision INTEGER NOT NULL, \n\trevision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\tdestructive BOOLEAN NOT NULL, \n\tstate VARCHAR(16) NOT NULL, \n\twindow_start TIMESTAMP WITH TIME ZONE NOT NULL, \n\twindow_finish TIMESTAMP WITH TIME ZONE NOT NULL, \n\tcoverage JSONB NOT NULL, \n\tintent_digest VARCHAR(64) NOT NULL, \n\tsource_basis JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, run_id, sample_id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, run_id) REFERENCES verification_run_identities (tenant_id, product_id, project_id, build_id, id) DEFERRABLE INITIALLY DEFERRED, \n\tFOREIGN KEY(tenant_id, sample_id) REFERENCES sample_usage_sentinels (tenant_id, sample_id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, sample_id) REFERENCES sample_units (tenant_id, product_id, project_id, build_id, id), \n\tCHECK (revision=1 AND sample_revision>0 AND actual_configuration_revision>0 AND window_finish>window_start AND visibility IN ('private','product')), \n\tCHECK ((destructive AND state='consumed') OR (NOT destructive AND state='reserved'))\n)\n\n", 'CREATE INDEX ix_sample_run_usages_tenant_id ON sample_run_usages (tenant_id)', 'CREATE UNIQUE INDEX one_destructive_sample_use ON sample_run_usages (tenant_id, sample_id) WHERE destructive')

OLD_FORMAL_CHECKS = ('(revision = 1 AND previous_request_id IS NULL AND previous_revision IS NULL) OR (previous_request_id IS NOT NULL AND previous_request_id <> id AND previous_revision IS NOT NULL AND revision = previous_revision + 1)', "COALESCE(request_snapshot->'timeline'->'actual_start' = 'null'::jsonb, false)", "COALESCE(request_snapshot->'timeline'->'disposed' = 'null'::jsonb, false)", "COALESCE(request_snapshot->'timeline'->'final_result' = 'null'::jsonb, false)", "COALESCE(request_snapshot->'timeline'->'preliminary_result' = 'null'::jsonb, false)", "COALESCE(request_snapshot->'timeline'->'promised_start' = 'null'::jsonb, false)", "COALESCE(request_snapshot->>'status' = status, false)", "operation IN ('verification.request.create','verification.method.prepare','verification.schedule.propose','verification.handoff.offer','verification.handoff.accept','verification.handoff.return')", 'revision > 0 AND build_revision > 0 AND preparation_revision > 0', "status <> 'accepted' OR COALESCE(jsonb_array_length(request_snapshot->'acceptances') > 0 AND jsonb_typeof(request_snapshot->'timeline'->'accepted') = 'object', false)", "status <> 'draft' OR COALESCE(request_snapshot->'samples' = '[]'::jsonb AND request_snapshot->'acceptances' = '[]'::jsonb AND request_snapshot->'returns' = '[]'::jsonb AND request_snapshot->'offered_coverage' = '[]'::jsonb, false)", "status <> 'draft' OR COALESCE(request_snapshot->'timeline'->'sample_ready' = 'null'::jsonb AND request_snapshot->'timeline'->'offered' = 'null'::jsonb AND request_snapshot->'timeline'->'accepted' = 'null'::jsonb, false)", "status = 'draft' OR COALESCE(jsonb_array_length(request_snapshot->'samples') > 0 AND jsonb_array_length(request_snapshot->'offered_coverage') > 0 AND jsonb_typeof(request_snapshot->'timeline'->'offered') = 'object', false)", "status IN ('draft','offered','accepted') AND visibility IN ('private','product')")

NEW_FORMAL_CHECKS = ('(revision = 1 AND previous_request_id IS NULL AND previous_revision IS NULL) OR (previous_request_id IS NOT NULL AND previous_request_id <> id AND previous_revision IS NOT NULL AND revision = previous_revision + 1)', "(status<>'scheduled' OR operation='verification.schedule.promise') AND (status<>'executing' OR operation='test.run.start')", "COALESCE(CASE WHEN status IN ('scheduled','executing') THEN jsonb_typeof(request_snapshot->'timeline'->'promised_start')='object' ELSE request_snapshot->'timeline'->'promised_start'='null'::jsonb END, false)", "COALESCE(CASE WHEN status='executing' THEN jsonb_typeof(request_snapshot->'timeline'->'actual_start')='object' ELSE request_snapshot->'timeline'->'actual_start'='null'::jsonb END, false)", "COALESCE(request_snapshot->'timeline'->'disposed' = 'null'::jsonb, false)", "COALESCE(request_snapshot->'timeline'->'final_result' = 'null'::jsonb, false)", "COALESCE(request_snapshot->'timeline'->'preliminary_result' = 'null'::jsonb, false)", "COALESCE(request_snapshot->>'status' = status, false)", "operation IN ('verification.request.create','verification.method.prepare','verification.schedule.propose','verification.handoff.offer','verification.handoff.accept','verification.handoff.return','verification.schedule.promise','test.run.start')", 'revision > 0 AND build_revision > 0 AND preparation_revision > 0', "status <> 'draft' OR COALESCE(request_snapshot->'samples' = '[]'::jsonb AND request_snapshot->'acceptances' = '[]'::jsonb AND request_snapshot->'returns' = '[]'::jsonb AND request_snapshot->'offered_coverage' = '[]'::jsonb, false)", "status <> 'draft' OR COALESCE(request_snapshot->'timeline'->'sample_ready' = 'null'::jsonb AND request_snapshot->'timeline'->'offered' = 'null'::jsonb AND request_snapshot->'timeline'->'accepted' = 'null'::jsonb, false)", "status = 'draft' OR COALESCE(jsonb_array_length(request_snapshot->'samples') > 0 AND jsonb_array_length(request_snapshot->'offered_coverage') > 0 AND jsonb_typeof(request_snapshot->'timeline'->'offered') = 'object', false)", "status IN ('draft','offered','accepted','scheduled','executing') AND visibility IN ('private','product')", "status NOT IN ('accepted','scheduled','executing') OR COALESCE(jsonb_array_length(request_snapshot->'acceptances') > 0 AND jsonb_typeof(request_snapshot->'timeline'->'accepted') = 'object', false)")
